import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:firebase_core/firebase_core.dart';

import '../backend.dart';
import '../services/cloudinary_photo_storage.dart';
import 'firebase_auth_repository.dart';
import 'firestore_incident_repository.dart';
import 'firestore_notification_repository.dart';

/// Initialises Firebase and returns the real [Backend].
///
/// [options]: pass `DefaultFirebaseOptions.currentPlatform` from
/// `lib/firebase_options.dart` (generated by `flutterfire configure`, and
/// git-ignored, so this file does not import it). On Android, leaving it
/// null also works: Firebase then reads `android/app/google-services.json`.
///
/// ```dart
/// import 'firebase_options.dart';
/// final backend = await createFirebaseBackend(
///   options: DefaultFirebaseOptions.currentPlatform,
/// );
/// ```
///
/// [cloudinary] defaults to the values passed with
/// `--dart-define-from-file=env.json`.
Future<Backend> createFirebaseBackend({
  FirebaseOptions? options,
  CloudinaryConfig cloudinary = const CloudinaryConfig.fromEnvironment(),
}) async {
  if (Firebase.apps.isEmpty) {
    await Firebase.initializeApp(options: options);
  }
  final firestore = FirebaseFirestore.instance;
  return Backend(
    auth: FirebaseAuthRepository(
      auth: FirebaseAuth.instance,
      firestore: firestore,
    ),
    incidents: FirestoreIncidentRepository(
      firestore: firestore,
      photos: CloudinaryPhotoStorage(config: cloudinary),
    ),
    notifications: FirestoreNotificationRepository(firestore: firestore),
  );
}
